    # its last proof removed proof_count times is unnecessary: the
    # checkpoint's count is cumulative proofs. A first batch on the
    # empty bootstrap is recognised directly.
    state = BranchStore._parse_proof_audit_checkpoint(checkpoint)
    previous_count = state["count"] - proof_count
    if previous_count <= 0:
        return BranchStore.create_proof_audit_checkpoint(())
    raise ValueError(
        "checkpoint repository resume evidence cannot be "
        "authenticated for a non-initial batch"
    )

